CREATE OR REPLACE FUNCTION public.set_updated_at() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$BEGIN NEW.updated_at=now();RETURN NEW;END$$; REVOKE EXECUTE ON FUNCTION public.set_updated_at() FROM PUBLIC,anon,authenticated;
CREATE TABLE public.payment_methods(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),user_id uuid NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE,label text NOT NULL,number text NOT NULL,instructions text,is_active boolean NOT NULL DEFAULT true,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now()); GRANT SELECT,INSERT,UPDATE,DELETE ON public.payment_methods TO authenticated; GRANT ALL ON public.payment_methods TO service_role; ALTER TABLE public.payment_methods ENABLE ROW LEVEL SECURITY; CREATE POLICY "own payment_methods" ON public.payment_methods FOR ALL USING(auth.uid()=user_id) WITH CHECK(auth.uid()=user_id);
CREATE TABLE public.trainings(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),user_id uuid NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE,name text NOT NULL,description text,pricing_type text NOT NULL CHECK(pricing_type IN('free','paid')),price numeric(12,2),payment_flow text CHECK(payment_flow IN('admin_numbers','client_contact')),video_link text,is_active boolean NOT NULL DEFAULT true,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now()); GRANT SELECT,INSERT,UPDATE,DELETE ON public.trainings TO authenticated; GRANT ALL ON public.trainings TO service_role; ALTER TABLE public.trainings ENABLE ROW LEVEL SECURITY; CREATE POLICY "own trainings" ON public.trainings FOR ALL USING(auth.uid()=user_id) WITH CHECK(auth.uid()=user_id);
CREATE TABLE public.training_files(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),user_id uuid NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE,training_id uuid NOT NULL REFERENCES public.trainings(id) ON DELETE CASCADE,file_path text,file_type text NOT NULL CHECK(file_type IN('video','pdf','document','link')),file_name text NOT NULL,size_bytes bigint,external_url text,created_at timestamptz NOT NULL DEFAULT now()); GRANT SELECT,INSERT,UPDATE,DELETE ON public.training_files TO authenticated; GRANT ALL ON public.training_files TO service_role; ALTER TABLE public.training_files ENABLE ROW LEVEL SECURITY; CREATE POLICY "own training_files" ON public.training_files FOR ALL USING(auth.uid()=user_id) WITH CHECK(auth.uid()=user_id);
CREATE TABLE public.products(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),user_id uuid NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE,name text NOT NULL,price numeric(12,2) NOT NULL DEFAULT 0,stock integer NOT NULL DEFAULT 0,description text,payment_flow text NOT NULL DEFAULT 'admin_numbers' CHECK(payment_flow IN('admin_numbers','client_contact')),is_active boolean NOT NULL DEFAULT true,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now()); GRANT SELECT,INSERT,UPDATE,DELETE ON public.products TO authenticated; GRANT ALL ON public.products TO service_role; ALTER TABLE public.products ENABLE ROW LEVEL SECURITY; CREATE POLICY "own products" ON public.products FOR ALL USING(auth.uid()=user_id) WITH CHECK(auth.uid()=user_id);
CREATE TABLE public.product_images(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),user_id uuid NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE,product_id uuid NOT NULL REFERENCES public.products(id) ON DELETE CASCADE,image_path text NOT NULL,sort_order integer NOT NULL DEFAULT 0,created_at timestamptz NOT NULL DEFAULT now()); GRANT SELECT,INSERT,UPDATE,DELETE ON public.product_images TO authenticated; GRANT ALL ON public.product_images TO service_role; ALTER TABLE public.product_images ENABLE ROW LEVEL SECURITY; CREATE POLICY "own product_images" ON public.product_images FOR ALL USING(auth.uid()=user_id) WITH CHECK(auth.uid()=user_id);
CREATE TABLE public.orders(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),user_id uuid NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE,type text NOT NULL CHECK(type IN('training','sales')),training_id uuid REFERENCES public.trainings(id) ON DELETE SET NULL,product_id uuid REFERENCES public.products(id) ON DELETE SET NULL,status text NOT NULL DEFAULT 'pending' CHECK(status IN('pending','awaiting_payment','payment_sent','accepted','refused','delivered')),client_fb_id text,client_fb_name text,client_whatsapp text,client_phone text,client_address text,payment_reference text,quantity integer NOT NULL DEFAULT 1,notes text,page_id text,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now()); GRANT SELECT,INSERT,UPDATE,DELETE ON public.orders TO authenticated; GRANT ALL ON public.orders TO service_role; ALTER TABLE public.orders ENABLE ROW LEVEL SECURITY; CREATE POLICY "own orders" ON public.orders FOR ALL USING(auth.uid()=user_id) WITH CHECK(auth.uid()=user_id);
CREATE TABLE public.client_ia_state(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),user_id uuid NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE,page_id text NOT NULL,client_fb_id text NOT NULL,client_fb_name text,ia_stopped boolean NOT NULL DEFAULT false,product_image_offsets jsonb NOT NULL DEFAULT '{}',created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),UNIQUE(user_id,page_id,client_fb_id)); GRANT SELECT,INSERT,UPDATE,DELETE ON public.client_ia_state TO authenticated; GRANT ALL ON public.client_ia_state TO service_role; ALTER TABLE public.client_ia_state ENABLE ROW LEVEL SECURITY; CREATE POLICY "own client_ia_state" ON public.client_ia_state FOR ALL USING(auth.uid()=user_id) WITH CHECK(auth.uid()=user_id);
CREATE TRIGGER trg_profiles_updated BEFORE UPDATE ON public.profiles FOR EACH ROW EXECUTE FUNCTION public.set_updated_at(); CREATE TRIGGER trg_prompts_updated BEFORE UPDATE ON public.prompts FOR EACH ROW EXECUTE FUNCTION public.set_updated_at(); CREATE TRIGGER trg_gemini_keys_updated BEFORE UPDATE ON public.gemini_keys FOR EACH ROW EXECUTE FUNCTION public.set_updated_at(); CREATE TRIGGER trg_facebook_pages_updated BEFORE UPDATE ON public.facebook_pages FOR EACH ROW EXECUTE FUNCTION public.set_updated_at(); CREATE TRIGGER trg_settings_updated BEFORE UPDATE ON public.settings FOR EACH ROW EXECUTE FUNCTION public.set_updated_at(); CREATE TRIGGER trg_scheduled_posts_updated BEFORE UPDATE ON public.scheduled_posts FOR EACH ROW EXECUTE FUNCTION public.set_updated_at(); CREATE TRIGGER trg_pm_updated BEFORE UPDATE ON public.payment_methods FOR EACH ROW EXECUTE FUNCTION public.set_updated_at(); CREATE TRIGGER trg_tr_updated BEFORE UPDATE ON public.trainings FOR EACH ROW EXECUTE FUNCTION public.set_updated_at(); CREATE TRIGGER trg_pr_updated BEFORE UPDATE ON public.products FOR EACH ROW EXECUTE FUNCTION public.set_updated_at(); CREATE TRIGGER trg_or_updated BEFORE UPDATE ON public.orders FOR EACH ROW EXECUTE FUNCTION public.set_updated_at(); CREATE TRIGGER trg_cs_updated BEFORE UPDATE ON public.client_ia_state FOR EACH ROW EXECUTE FUNCTION public.set_updated_at();